--needed: function to go from input [string] to [(x1,y1,nx,ny)] tuples

-- combine two strings into a list of x and y coordinate tuples
combo :: [Int] -> [Int] -> [(Int,Int)]
combo xs ys = (,) <$> xs <*> ys

-- create a list of the x columns containing a claim
claimX :: (Int,Int,Int,Int) -> [Int]
claimX (x1, y1, nx, ny) = [x1..(x1+nx-1)]

-- create a list of the y columns containing a claim
claimY :: (Int,Int,Int,Int) -> [Int]
claimY (x1, y1, nx, ny) = [y1..(y1+ny-1)]

-- create a list of the (x,y) coordinates claimed in one claim
claim :: (Int,Int,Int,Int) -> [(Int,Int)]
claim inTup = combo (claimX inTup) (claimY inTup)

-- create a map of one claim key: (x,y)-coord value:1
claimMap :: (Int,Int,Int,Int) -> M.Map (Int, Int) Int
claimMap = M.fromList . map (\x-> (x,1)) . claim

-- merijn: unionsWith (met een s) kun je gebruiken
-- om een lijst van maps naar een map te maken
combineMaps :: [M.Map (Int, Int) Int] -> M.Map (Int,Int) Int
combineMaps xs = go xs M.empty
    where
        go [] result = result
        go (x:xs) result = go xs (M.unionWith (+) x result)
-- foldable instance voor Map k, met foldMap en Sum Int        
allClaims :: [(Int,Int,Int,Int)] -> [((Int, Int), Int)]
allClaims xs = M.toList . combineMaps $ map claimMap xs

answer :: [(Int,Int,Int,Int)] -> Int
answer xs = go (allClaims xs) 0
    where
        go [] result = result
        go ((x,y):xs) result = case y >1 of
                                    True -> go xs (result + 1)
                                    False -> go xs result
 --       go ((x,y):xs) result
 --         | y > 1 = go xs (result + 1)
 --         | otherwise = go xs result

